import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { useStateContext } from "../../contexts/ContextProvider";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import CustomForm from "../../components/forms/CustomForm";
import CustomFormItem from "../../components/forms/CustomFormItem";
import CustomInput from "../../components/forms/CustomInput";
import CustomSelectReactSelect from "../../components/forms/CustomSelectReactSelect";
import CustomDatePicker from "../../components/forms/CustomDatePicker";
import useApi from "../../hooks/useApi";
import "react-datepicker/dist/react-datepicker.css";
import Loading from "../../components/Loading";
import countriesApi from "../../api/countriesApi";
import countiesApi from "../../api/countiesApi";
import entitiesApi from "../../api/entitiesApi";
import { Button } from "@heroui/react";
import usersApi from "../../api/usersApi";
import entityTypes from "../../data/entityTypes";
import entityOwnerships from "../../data/entityOwnerships";
import categoriesApi from "../../api/categoriesApi";
import entityLevels from "../../data/entityLevels";

const AddCorporateEntity = () => {
  const navigate = useNavigate();
  const moment = require("moment");

  const user = useSelector((state) => state.Auth.user);
  // const errors = useSelector((state) => state.Auth.errors);
  const [categories, setCategories] = useState();
  const [errors, seterrors] = useState([]);
  const loading = useSelector((state) => state.Auth.loading);
  const created = useSelector((state) => state.Auth.created);
  const { currentColor } = useStateContext();

  const entitiesActionsApi = useApi(entitiesApi.entitiesAction);

  const handleEntitiesAction = async (data) => {
    console.log("data at edit", data);
    const result = await entitiesActionsApi.request(data);
    console.log("result at edit", result);

    if (result.ok) {
      if (result.data.response_code === 0) {
        toast.success(result.data.response_message);
        window.location.reload();
      } else {
        toast.error(result.data.response_message);
      }
      seterrors(result.data.errors);
    } else {
      seterrors(result.data.errors);
    }
  };

  const formik = useFormik({
    initialValues: {
      title: "",
      description: "",
      country: "",
      county: "",
      entity_type: "",
      entity_ownership: "",
      town: "",
      road: "",
      building: "",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      let arr = [];
      if (values.categories && values.categories.length) {
        values.categories.map((x) => {
          arr.push(x.value);
        });
      }

      if (!isKenyan) {
        handleEntitiesAction({
          action: "CreateInternationalEntity",
          entity_details: {
            title: values.title,
            entity_type: values.entity_type.value,
            entity_ownership: values.entity_ownership.value,
            entity_code: values.entity_code,
            country: values.country.value,
            county: values.county.value,
            categories: arr,
            town: values.town,
            road: values.road,
            building: values.building,
            organization: values.organization ? values.organization.value : "",
            entity_level: values.entity_level.value,
          },
        });
      } else {
        handleEntitiesAction({
          action: "CreateLocalEntity",
          entity_details: {
            title: values.title,
            entity_type: values.entity_type.value,
            entity_ownership: values.entity_ownership.value,
            entity_code: values.entity_code,
            country: values.country.value,
            county: values.county.value,
            categories: arr,
            town: values.town,
            road: values.road,
            building: values.building,
            organization: values.organization ? values.organization.value : "",
            entity_level: values.entity_level.value,
          },
        });
      }

      // resetForm();
    },
  });

  useEffect(() => {
    if (created && user) {
      navigate("/login");
    }
  }, [created, user]);

  //Register

  const createCorporateUserApi = useApi(usersApi.createCorporateUserAction);

  const registerUser = async (data) => {
    const res = await createCorporateUserApi.request(data);
    console.log("Result", res);
    seterrors(res.data.errors.errors);
  };
  useEffect(() => {
    if (
      createCorporateUserApi.data &&
      createCorporateUserApi.data.response_code === 1
    ) {
      toast.error(createCorporateUserApi.response_message);
    }

    // console.log("doRegisterApi.data", doRegisterApi.data);
  }, [createCorporateUserApi.data]);

  //Countries
  const [countries, setCountries] = useState([]);
  const getCountriesApi = useApi(countriesApi.countriesAction);
  useEffect(() => {
    if (getCountriesApi.data && getCountriesApi.data.length) {
      setCountries(
        getCountriesApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("Countries", getCountriesApi.data);
  }, [getCountriesApi.data]);

  const getCountries = async () => {
    await getCountriesApi.request({
      action: "GetCountries",
    });
  };
  const [isKenyan, setisKenyan] = useState(false);
  //Counties
  const [counties, setCounties] = useState([]);
  const getCountiesApi = useApi(countiesApi.countiesAction);
  const getCounties = async () => {
    await getCountiesApi.request({
      action: "GetCounties",
    });
  };

  useEffect(() => {
    if (getCountiesApi.data && getCountiesApi.data.length) {
      setCounties(
        getCountiesApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("Countries", getCountiesApi.data);
  }, [getCountiesApi.data]);

  //Organizations

  const [organizations, setOrganizations] = useState([]);
  const getOrganizationsApi = useApi(entitiesApi.entitiesActionAdmin);
  const getOrganizations = async (action) => {
    setOrganizations([]);
    await getOrganizationsApi.request({
      action: action,
    });
  };

  useEffect(() => {
    getOrganizations("GetOrganizations");
  }, []);

  useEffect(() => {
    if (getOrganizationsApi.data && getOrganizationsApi.data.length) {
      setOrganizations(
        getOrganizationsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("getOrganizationsApi.data", getOrganizationsApi.data);
  }, [getOrganizationsApi.data]);

  //Entities
  const [entities, setEntities] = useState([]);
  const getEntiesApi = useApi(entitiesApi.entitiesAction);
  const getEntities = async () => {
    await getEntiesApi.request({
      action: "GetAllEntities",
    });
  };

  useEffect(() => {
    if (getEntiesApi.data && getEntiesApi.data.length) {
      setEntities(
        getEntiesApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("Countries", getEntiesApi.data);
  }, [getEntiesApi.data]);

  //Categories

  const categoriesActionsApi = useApi(categoriesApi.categoriesAction);

  const loadCategories = async (data) => {
    await categoriesActionsApi.request({
      action: "GetAllCategories",
    });
  };

  useEffect(() => {
    if (categoriesActionsApi.data) {
      if (categoriesActionsApi.data.length) {
        setCategories(
          categoriesActionsApi.data.map((i) => ({
            label: i.title,
            value: i.id,
          }))
        );
      }
    }
  }, [categoriesActionsApi.data]);

  useEffect(() => {
    getCountries();
    getCounties();
    getEntities();
    loadCategories();
  }, []);

  const handleSelectCountry = (value) => {
    if (value) {
      formik.setFieldValue("country", value);

      if (value.label === "KENYA") {
        setisKenyan(true);
      } else {
        setisKenyan(false);
      }
    } else {
      return;
    }
  };

  return (
    <div className=" grid grid-cols-1 md:grid-cols-12 mt-16 md:mt-4">
      <div className=" col-span-3 hidden md:block"></div>
      <div className=" col-span-6">
        {createCorporateUserApi.loading ? (
          <Loading loading={createCorporateUserApi.loading} />
        ) : (
          <div className="container m-auto bg-gray-100 w-full">
            <div className="m-1">
              <ToastContainer position="bottom-center" theme="colored" />
            </div>
            {errors && errors.length ? (
              <div className="bg-red-500 w-full">
                {errors.map((x) => {
                  return (
                    <p className="text-white my-1 font-bold text-lg">{x}</p>
                  );
                })}
              </div>
            ) : (
              <div></div>
            )}
            <div className="text-center py-1">
              <h2 className="mt-2 text-center text-2xl font-extrabold text-gray-900">
                Add Corporate Entity
              </h2>
            </div>
            <div className=" flex justify-center items-center bg-gray-100  w-full">
              {loading ? (
                <Loading loading={loading} />
              ) : (
                <CustomForm
                  layout="vertical"
                  handleFinish={formik.handleSubmit}
                  className="w-full"
                >
                  <div className="grid grid-cols-1 md:grid-cols-2  gap-4  justify-center items-center px-5 w-full">
                    <CustomFormItem
                      touched={formik.touched.country}
                      error={formik.errors.country}
                    >
                      <CustomSelectReactSelect
                        className="text-start"
                        name="country"
                        id="country"
                        label="Select country"
                        size="large"
                        onChange={(value) => handleSelectCountry(value)}
                        value={formik.values.country}
                        placeholder="Select country"
                        options={countries}
                      />
                    </CustomFormItem>
                    <CustomFormItem
                      touched={formik.touched.organization}
                      error={formik.errors.organization}
                    >
                      <CustomSelectReactSelect
                        className="text-start"
                        name="organization"
                        id="organization"
                        label="Select organization"
                        size="large"
                        onChange={(value) =>
                          formik.setFieldValue("organization", value)
                        }
                        value={formik.values.organization}
                        placeholder="Select organization"
                        options={organizations}
                      />
                    </CustomFormItem>

                    <CustomFormItem
                      touched={formik.touched.entity_type}
                      error={formik.errors.entity_type}
                    >
                      <CustomSelectReactSelect
                        className="text-start"
                        name="entity_type"
                        id="entity_type"
                        label="Select entity_type"
                        size="large"
                        onChange={(value) =>
                          formik.setFieldValue("entity_type", value)
                        }
                        value={formik.values.entity_type}
                        placeholder="Select entity_type"
                        options={entityTypes}
                      />
                    </CustomFormItem>
                    <CustomFormItem
                      touched={formik.touched.entity_level}
                      error={formik.errors.entity_level}
                    >
                      <CustomSelectReactSelect
                        className="text-start"
                        name="entity_level"
                        id="entity_level"
                        label="Select entity level"
                        size="large"
                        onChange={(value) =>
                          formik.setFieldValue("entity_level", value)
                        }
                        value={formik.values.entity_level}
                        placeholder="Select entity level"
                        options={entityLevels}
                      />
                    </CustomFormItem>

                    <CustomFormItem
                      touched={formik.touched.entity_ownership}
                      error={formik.errors.entity_ownership}
                    >
                      <CustomSelectReactSelect
                        className="text-start"
                        name="entity_ownership"
                        id="entity_ownership"
                        label="Select entity ownership"
                        size="large"
                        onChange={(value) =>
                          formik.setFieldValue("entity_ownership", value)
                        }
                        value={formik.values.entity_ownership}
                        placeholder="Select entity ownership"
                        options={entityOwnerships}
                      />
                    </CustomFormItem>

                    <CustomFormItem
                      touched={formik.touched.title}
                      error={formik.errors.title}
                    >
                      <CustomInput
                        className="uppercase"
                        required={true}
                        id="title"
                        name="title"
                        onChange={formik.handleChange}
                        placeholder="Enter entity title"
                        size="large"
                        type="text"
                        value={formik.values.title}
                        label="Enter entity title"
                      />
                    </CustomFormItem>

                    {isKenyan && (
                      <CustomFormItem
                        touched={formik.touched.county}
                        error={formik.errors.county}
                      >
                        <CustomSelectReactSelect
                          className="text-start"
                          name="county"
                          id="county"
                          label="Select  region"
                          size="large"
                          onChange={(value) =>
                            formik.setFieldValue("county", value)
                          }
                          value={formik.values.county}
                          placeholder="Select region county"
                          options={counties}
                        />
                      </CustomFormItem>
                    )}

                    {isKenyan && (
                      <CustomFormItem
                        touched={formik.touched.categories}
                        error={formik.errors.categories}
                      >
                        <CustomSelectReactSelect
                          className="text-start"
                          name="categories"
                          id="categories"
                          label="Select appropriate categories"
                          size="large"
                          onChange={(value) =>
                            formik.setFieldValue("categories", value)
                          }
                          value={formik.values.categories}
                          placeholder="Select appropriate categories"
                          options={categories}
                          isMulti={true}
                        />
                      </CustomFormItem>
                    )}

                    {isKenyan && (
                      <CustomFormItem
                        touched={formik.touched.town}
                        error={formik.errors.town}
                      >
                        <CustomInput
                          required={true}
                          id="town"
                          name="town"
                          onChange={formik.handleChange}
                          placeholder="Enter entity town"
                          size="large"
                          type="text"
                          value={formik.values.town}
                          label="Enter entity town"
                        />
                      </CustomFormItem>
                    )}

                    {isKenyan && (
                      <CustomFormItem
                        touched={formik.touched.road}
                        error={formik.errors.road}
                      >
                        <CustomInput
                          required={true}
                          id="road"
                          name="road"
                          onChange={formik.handleChange}
                          placeholder="Enter entity road"
                          size="large"
                          type="text"
                          value={formik.values.road}
                          label="Enter entity road"
                        />
                      </CustomFormItem>
                    )}

                    {isKenyan && (
                      <CustomFormItem
                        touched={formik.touched.building}
                        error={formik.errors.building}
                      >
                        <CustomInput
                          required={true}
                          id="building"
                          name="building"
                          onChange={formik.handleChange}
                          placeholder="Enter entity building"
                          size="large"
                          type="text"
                          value={formik.values.building}
                          label="Enter entity building"
                        />
                      </CustomFormItem>
                    )}
                  </div>
                  <div className="px-5 my-5">
                    <button
                      style={{ background: currentColor }}
                      className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50 "
                      color="primary"
                      type="submit"
                    >
                      Submit
                    </button>
                  </div>
                </CustomForm>
              )}
            </div>
          </div>
        )}
      </div>
      <div className=" col-span-3 hidden md:block"></div>
    </div>
  );
};

export default AddCorporateEntity;
